import numpy as np
rng = np.random.default_rng(0)

def power(n, p0=0.90, p1=0.93, trials=20000):
    a = rng.binomial(n, p0, trials) / n
    b = rng.binomial(n, p1, trials) / n
    return float((b - a > 0.0).mean())

for n in (50, 100, 200, 400, 800):
    print(n, round(power(n), 3))
